import json,subprocess;from pathlib import Path;s=subprocess.run(['systemctl','--user','is-active','prediction-research-lifecycle-supervisor.service'],capture_output=True,text=True).stdout.strip();p=Path.home()/'.local/state/prediction-research/supervisor_status.json';d=json.loads(p.read_text()) if p.exists() else {};print(json.dumps({'service':s,'status_file':p.exists(),'supervisor_status':d.get('status'),'interval':d.get('check_interval_seconds'),'guardrails':d.get('guardrails'),'incidents_seen':d.get('incidents_seen')}))